<?php
namespace App\Galika\Services;
use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;
class OutboxService{
 public function publish(string $topic,array $payload,?int $userId=null,?string $type=null,?int $id=null):string{$event=(string)Str::uuid();DB::table('galika_outbox')->insert(['event_id'=>$event,'user_id'=>$userId,'topic'=>$topic,'aggregate_type'=>$type,'aggregate_id'=>$id,'payload'=>json_encode($payload,JSON_THROW_ON_ERROR),'status'=>'PENDING','available_at'=>now(),'created_at'=>now(),'updated_at'=>now()]);return $event;}
 public function lease(int $limit=50,int $seconds=120):array{return DB::transaction(function()use($limit,$seconds){$rows=DB::table('galika_outbox')->whereIn('status',['PENDING','RETRY'])->where(fn($q)=>$q->whereNull('available_at')->orWhere('available_at','<=',now()))->where(fn($q)=>$q->whereNull('leased_until')->orWhere('leased_until','<',now()))->orderBy('id')->limit($limit)->lockForUpdate()->get();foreach($rows as $r)DB::table('galika_outbox')->where('id',$r->id)->update(['status'=>'LEASED','leased_until'=>now()->addSeconds($seconds),'attempts'=>$r->attempts+1,'updated_at'=>now()]);return $rows->map(fn($r)=>(array)$r)->all();});}
 public function done(int $id):void{DB::table('galika_outbox')->where('id',$id)->update(['status'=>'DONE','delivered_at'=>now(),'leased_until'=>null,'last_error'=>null,'updated_at'=>now()]);}
 public function retry(int $id,string $error,int $attempt):void{DB::table('galika_outbox')->where('id',$id)->update(['status'=>'RETRY','leased_until'=>null,'last_error'=>$error,'available_at'=>now()->addSeconds(min(3600,15*(2**min(7,$attempt)))),'updated_at'=>now()]);}
}